import type { QueryDescription } from '../describe.js';
import { nullable, propertyKey, stringLiteral, tsTypeFor } from '../types/emit.js';

export interface GeneratedEntry {
  text: string;
  description: QueryDescription;
}

/** Renders the `typeduck.d.ts` module augmentation for the given queries. */
export function emitDeclarations(entries: readonly GeneratedEntry[]): string {
  const sorted = [...entries].sort((a, b) => (a.text < b.text ? -1 : a.text > b.text ? 1 : 0));
  const lines: string[] = [
    '// Generated by typeduck. Do not edit.',
    "import type { JS } from '@duckdb/node-api';",
    '',
    "declare module 'typeduck' {",
    '  interface Queries {',
  ];
  for (const { text, description } of sorted) {
    lines.push(`    ${stringLiteral(text)}: {`);
    lines.push(`      row: ${rowType(description)};`);
    lines.push(`      params: ${paramsType(description)};`);
    lines.push('    };');
  }
  lines.push('  }', '}', '');
  return lines.join('\n');
}

export function rowType(description: QueryDescription): string {
  if (description.columns.length === 0) {
    return '{}';
  }
  const entries = description.columns.map(
    (c) =>
      `${propertyKey(c.key)}: ${c.type === null ? 'unknown' : nullable(tsTypeFor(c.type, 'output'))}`,
  );
  return `{ ${entries.join('; ')} }`;
}

export function paramsType(description: QueryDescription): string {
  const { params, positional } = description;
  if (params.length === 0) {
    return '[]';
  }
  const render = (p: QueryDescription['params'][number]) =>
    p.type === null ? 'unknown' : nullable(tsTypeFor(p.type, 'input'));
  if (positional) {
    return `[${params.map(render).join(', ')}]`;
  }
  return `{ ${params.map((p) => `${propertyKey(p.name)}: ${render(p)}`).join('; ')} }`;
}
